const STALE_AFTER_MINUTES = 120;
const now = Date.now();
const thresholdMs = STALE_AFTER_MINUTES * 60 * 1000;

const rows = $input.all()
  .map(item => item.json)
  .filter(row => row && row.run_id && row.status === 'RUNNING');

const staleRuns = [];
const activeCandidates = [];
const invalidTimestamps = [];

for (const row of rows) {
  const submitted = Date.parse(row.submitted_at || '');

  if (!Number.isFinite(submitted)) {
    invalidTimestamps.push({
      run_id: row.run_id,
      seller_id: row.seller_id,
      reason: 'MISSING_OR_INVALID_SUBMITTED_AT'
    });
    continue;
  }

  const ageMs = now - submitted;

  if (ageMs < 0) {
    invalidTimestamps.push({
      run_id: row.run_id,
      seller_id: row.seller_id,
      reason: 'SUBMITTED_AT_IN_FUTURE'
    });
    continue;
  }

  const result = {
    run_id: row.run_id,
    seller_id: row.seller_id,
    submitted_at: row.submitted_at,
    age_minutes: Math.floor(ageMs / 60000)
  };

  if (ageMs >= thresholdMs) {
    staleRuns.push({
      ...result,
      recovery_status: 'REQUIRES_INVESTIGATION',
      reason: 'RUNNING_STATUS_EXCEEDED_THRESHOLD'
    });
  } else {
    activeCandidates.push(result);
  }
}

return [{
  json: {
    checked_at: new Date(now).toISOString(),
    threshold_minutes: STALE_AFTER_MINUTES,
    running_count: rows.length,
    stale_count: staleRuns.length,
    active_candidate_count: activeCandidates.length,
    invalid_timestamp_count: invalidTimestamps.length,
    stale_runs: staleRuns,
    active_candidates: activeCandidates,
    invalid_timestamps: invalidTimestamps,
    detection_only: true
  }
}];
